function SnoringImageSlider() {
  const images = [snoring1, snoring2, snoring3, snoring4, snoring5, snoring6];
  const visible = 3;
  const [current, setCurrent] = React.useState(0);
  const total = images.length;
  const maxIndex = Math.ceil(total / visible);
  const next = () => setCurrent(c => (c + visible < total ? c + visible : c));
  const prev = () => setCurrent(c => (c - visible >= 0 ? c - visible : 0));
  const goTo = idx => setCurrent(idx * visible);
  return (
    <div className="w-full flex flex-col items-center">
      <div className="flex items-center justify-center gap-4 w-full">
        <button onClick={prev} className="bg-white border border-gray-300 text-red-700 rounded-full p-3 shadow-lg hover:bg-red-100 transition">&#8592;</button>
        <div className="flex gap-8">
          {images.slice(current, current + visible).map((image, idx) => (
            <div key={current + idx} className="w-64 h-48 bg-gradient-to-br from-gray-200 to-gray-300 flex items-center justify-center rounded-2xl shadow-xl transform hover:scale-105 transition-transform duration-300 animate-img-pop">
              <img src={image} alt={`Snoring Image ${current + idx + 1}`} className="w-full h-full object-cover rounded-2xl" />
            </div>
          ))}
        </div>
        <button onClick={next} className="bg-white border border-gray-300 text-red-700 rounded-full p-3 shadow-lg hover:bg-red-100 transition">&#8594;</button>
      </div>
      <div className="flex justify-center mt-6 gap-2">
        {Array.from({ length: maxIndex }).map((_, idx) => (
          <button
            key={idx}
            onClick={() => goTo(idx)}
            className={`w-3 h-3 rounded-full ${current === idx * visible ? 'bg-red-500' : 'bg-gray-300'} transition`}
            aria-label={`Go to slide ${idx + 1}`}
          />
        ))}
      </div>
    </div>
  );
}

